final class ReferenceMonitor {
    private let store: PolicyStore        // no setter, never exposed
    private let ledger: Ledger            // the protected resource, private to this declaration

    init(store: PolicyStore, ledger: Ledger) { self.store = store; self.ledger = ledger }

    func read(_ subject: Subject, id: ObjectID) throws -> Record {
        guard let principal = subject.principal else { throw Deny.noPrincipal }   // fail closed
        guard store.allows(principal, .read, id) else { throw Deny.noRule }
        return try ledger.record(id)      // the only exported path to Ledger
    }
}
